    def count_winners(s):
        n = len(s)
        dp = [set() for _ in range(n)]
        for i in range(n // 2):
            dp[i] = {i * 2 + 1, i * 2 + 2}
        for i in range(n // 2, n):
            if s[i] == '0':
                dp[i] = dp[2 * i - n + 1]
            elif s[i] == '1':
                dp[i] = dp[2 * i - n + 2]
            else:
                dp[i] = dp[2 * i - n + 1] | dp[2 * i - n + 2]
        return len(dp[-1])

    for p, c in queries:
        s[p - 1] = c
